class FoodRatings {
    private final java.util.Map<String, String> foodCuisine = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> foodRating = new java.util.HashMap<>();
    private final java.util.Map<String, java.util.TreeSet<String>> cuisineFoods = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            cuisineFoods.computeIfAbsent(cuisines[i], key -> new java.util.TreeSet<>((left, right) -> {
                int ratingOrder = Integer.compare(foodRating.get(right), foodRating.get(left));
                if (ratingOrder != 0) {
                    return ratingOrder;
                }
                return left.compareTo(right);
            })).add(foods[i]);
        }
    }

    public void changeRating(String food, int newRating) {
        String cuisine = foodCuisine.get(food);
        java.util.TreeSet<String> set = cuisineFoods.get(cuisine);
        set.remove(food);
        foodRating.put(food, newRating);
        set.add(food);
    }

    public String highestRated(String cuisine) {
        return cuisineFoods.get(cuisine).first();
    }
}

class FoodRatings {
    private static class Entry {
        final String food;
        final int rating;

        Entry(String food, int rating) {
            this.food = food;
            this.rating = rating;
        }
    }

    private final java.util.Map<String, String> foodCuisine = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> foodRating = new java.util.HashMap<>();
    private final java.util.Map<String, java.util.PriorityQueue<Entry>> cuisineHeap = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        java.util.Comparator<Entry> bestFirst = (left, right) -> {
            if (left.rating != right.rating) {
                return Integer.compare(right.rating, left.rating);
            }
            return left.food.compareTo(right.food);
        };
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            cuisineHeap.computeIfAbsent(cuisines[i], key -> new java.util.PriorityQueue<>(bestFirst))
                    .offer(new Entry(foods[i], ratings[i]));
        }
    }

    public void changeRating(String food, int newRating) {
        foodRating.put(food, newRating);
        String cuisine = foodCuisine.get(food);
        cuisineHeap.get(cuisine).offer(new Entry(food, newRating));
    }

    public String highestRated(String cuisine) {
        java.util.PriorityQueue<Entry> heap = cuisineHeap.get(cuisine);
        while (true) {
            Entry top = heap.peek();
            if (top.rating == foodRating.get(top.food)) {
                return top.food;
            }
            heap.poll();
        }
    }
}

class FoodRatings {
    private final java.util.Map<String, String> foodCuisine = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> foodRating = new java.util.HashMap<>();
    private final java.util.Map<String, java.util.TreeMap<Integer, java.util.TreeSet<String>>> cuisineBuckets = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            addToBucket(cuisines[i], ratings[i], foods[i]);
        }
    }

    public void changeRating(String food, int newRating) {
        String cuisine = foodCuisine.get(food);
        int oldRating = foodRating.get(food);
        removeFromBucket(cuisine, oldRating, food);
        foodRating.put(food, newRating);
        addToBucket(cuisine, newRating, food);
    }

    public String highestRated(String cuisine) {
        java.util.Map.Entry<Integer, java.util.TreeSet<String>> best = cuisineBuckets.get(cuisine).lastEntry();
        return best.getValue().first();
    }

    private void addToBucket(String cuisine, int rating, String food) {
        cuisineBuckets.computeIfAbsent(cuisine, key -> new java.util.TreeMap<>())
                .computeIfAbsent(rating, key -> new java.util.TreeSet<>())
                .add(food);
    }

    private void removeFromBucket(String cuisine, int rating, String food) {
        java.util.TreeMap<Integer, java.util.TreeSet<String>> buckets = cuisineBuckets.get(cuisine);
        java.util.TreeSet<String> names = buckets.get(rating);
        names.remove(food);
        if (names.isEmpty()) {
            buckets.remove(rating);
        }
    }
}

class FoodRatings {
    private final java.util.Map<String, String> foodCuisine = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> foodRating = new java.util.HashMap<>();
    private final java.util.Map<String, FoodHeap> cuisineHeap = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            cuisineHeap.computeIfAbsent(cuisines[i], key -> new FoodHeap()).add(foods[i]);
        }
    }

    public void changeRating(String food, int newRating) {
        foodRating.put(food, newRating);
        cuisineHeap.get(foodCuisine.get(food)).update(food);
    }

    public String highestRated(String cuisine) {
        return cuisineHeap.get(cuisine).peek();
    }

    private class FoodHeap {
        private final java.util.ArrayList<String> heap = new java.util.ArrayList<>();
        private final java.util.Map<String, Integer> position = new java.util.HashMap<>();

        void add(String food) {
            position.put(food, heap.size());
            heap.add(food);
            siftUp(heap.size() - 1);
        }

        void update(String food) {
            int index = position.get(food);
            siftUp(index);
            siftDown(position.get(food));
        }

        String peek() {
            return heap.get(0);
        }

        private void siftUp(int index) {
            while (index > 0) {
                int parent = (index - 1) / 2;
                if (!better(heap.get(index), heap.get(parent))) {
                    break;
                }
                swap(index, parent);
                index = parent;
            }
        }

        private void siftDown(int index) {
            while (true) {
                int left = index * 2 + 1;
                int right = left + 1;
                int best = index;
                if (left < heap.size() && better(heap.get(left), heap.get(best))) {
                    best = left;
                }
                if (right < heap.size() && better(heap.get(right), heap.get(best))) {
                    best = right;
                }
                if (best == index) {
                    break;
                }
                swap(index, best);
                index = best;
            }
        }

        private boolean better(String left, String right) {
            int leftRating = foodRating.get(left);
            int rightRating = foodRating.get(right);
            if (leftRating != rightRating) {
                return leftRating > rightRating;
            }
            return left.compareTo(right) < 0;
        }

        private void swap(int left, int right) {
            String a = heap.get(left);
            String b = heap.get(right);
            heap.set(left, b);
            heap.set(right, a);
            position.put(a, right);
            position.put(b, left);
        }
    }
}

class FoodRatings {
    private final java.util.Map<String, String> foodCuisine = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> foodRating = new java.util.HashMap<>();
    private final java.util.Map<String, CuisineBlock> cuisineBlocks = new java.util.HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            cuisineBlocks.computeIfAbsent(cuisines[i], key -> new CuisineBlock()).foods.add(foods[i]);
        }
        for (CuisineBlock block : cuisineBlocks.values()) {
            block.build();
        }
    }

    public void changeRating(String food, int newRating) {
        foodRating.put(food, newRating);
        cuisineBlocks.get(foodCuisine.get(food)).refresh(food);
    }

    public String highestRated(String cuisine) {
        return cuisineBlocks.get(cuisine).best();
    }

    private class CuisineBlock {
        private final java.util.ArrayList<String> foods = new java.util.ArrayList<>();
        private final java.util.Map<String, Integer> index = new java.util.HashMap<>();
        private final java.util.ArrayList<String> blockBest = new java.util.ArrayList<>();
        private int blockSize;

        void build() {
            java.util.Collections.sort(foods);
            blockSize = (int) Math.sqrt(foods.size()) + 1;
            int blockCount = (foods.size() + blockSize - 1) / blockSize;
            for (int i = 0; i < foods.size(); i++) {
                index.put(foods.get(i), i);
            }
            for (int block = 0; block < blockCount; block++) {
                blockBest.add(null);
                recompute(block);
            }
        }

        void refresh(String food) {
            recompute(index.get(food) / blockSize);
        }

        String best() {
            String answer = null;
            for (String candidate : blockBest) {
                if (candidate != null && (answer == null || better(candidate, answer))) {
                    answer = candidate;
                }
            }
            return answer;
        }

        private void recompute(int block) {
            int start = block * blockSize;
            int end = Math.min(foods.size(), start + blockSize);
            String bestFood = null;
            for (int i = start; i < end; i++) {
                String food = foods.get(i);
                if (bestFood == null || better(food, bestFood)) {
                    bestFood = food;
                }
            }
            blockBest.set(block, bestFood);
        }

        private boolean better(String left, String right) {
            int leftRating = foodRating.get(left);
            int rightRating = foodRating.get(right);
            if (leftRating != rightRating) {
                return leftRating > rightRating;
            }
            return left.compareTo(right) < 0;
        }
    }
}
